package com.bookeat;
import com.bookeat.dining.service.DiningRules;import com.bookeat.dining.enums.DiningStatus;import com.bookeat.payment.service.PaymentRules;import com.bookeat.wallet.service.WalletRules;import com.bookeat.report.service.ReportExporter;
import java.time.*;import java.math.*;import java.util.*;import java.nio.charset.StandardCharsets;import java.io.*;import java.util.zip.*;import javax.xml.parsers.DocumentBuilderFactory;
public class FinalPhaseRuleChecks {
 static int assertions;static void check(boolean b){assertions++;if(!b)throw new AssertionError("Check "+assertions+" failed");}
 static void rejects(Runnable r){boolean rejected=false;try{r.run();}catch(IllegalArgumentException|ArithmeticException e){rejected=true;}check(rejected);}
 public static void dining(){Instant start=Instant.parse("2026-09-13T10:00:00Z");check(!DiningRules.arrivalWindow(start.minusNanos(1),start,start.plusSeconds(3600),start.plusSeconds(900)));check(DiningRules.arrivalWindow(start,start,start.plusSeconds(3600),start.plusSeconds(900)));check(!DiningRules.arrivalWindow(start.plusSeconds(900),start,start.plusSeconds(3600),start.plusSeconds(900)));check(DiningRules.withinRadius(0.1,100));check(!DiningRules.withinRadius(0.10001,100));check(!DiningRules.withinRadius(Double.NaN,100));for(var s:DiningStatus.values())check(DiningRules.canOrder(s)==(s==DiningStatus.DINING||s==DiningStatus.CHECKED_IN));}
 public static void money(){for(int cents=0;cents<5000;cents++){BigDecimal amount=BigDecimal.valueOf(cents,2);check(PaymentRules.minor(amount)==cents);check(PaymentRules.major(cents).compareTo(amount)==0);BigDecimal commission=PaymentRules.commission(amount,true,new BigDecimal("12.5"));check(commission.signum()>=0&&commission.compareTo(amount)<=0);}rejects(()->PaymentRules.minor(new BigDecimal("1.001")));rejects(()->PaymentRules.minor(new BigDecimal("-1")));rejects(()->PaymentRules.commission(BigDecimal.TEN,true,new BigDecimal("101")));check(PaymentRules.commission(new BigDecimal("99.99"),true,new BigDecimal("10")).equals(new BigDecimal("10.00")));check(PaymentRules.refundAllowed(BigDecimal.TEN,new BigDecimal("9.99"),new BigDecimal("0.01")));check(!PaymentRules.refundAllowed(BigDecimal.TEN,new BigDecimal("9.99"),new BigDecimal("0.02")));check(!PaymentRules.refundAllowed(BigDecimal.TEN,BigDecimal.ZERO,BigDecimal.ZERO));}
 public static void signatures(){byte[] message="what do ya want for nothing?".getBytes(StandardCharsets.UTF_8);String expected="5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843";check(PaymentRules.signature("Jefe",message,expected));check(!PaymentRules.signature("wrong",message,expected));check(!PaymentRules.signature("Jefe","tampered".getBytes(StandardCharsets.UTF_8),expected));check(!PaymentRules.signature("Jefe",message,"bad"));check(!PaymentRules.signature("",message,expected));}
 public static void wallet(){for(int n=1;n<=2000;n++){BigDecimal amount=WalletRules.redeem(n,n,new BigDecimal("0.25"));check(amount.equals(BigDecimal.valueOf(n).multiply(new BigDecimal("0.25"))));var debt=WalletRules.adjustPoints(0,0,-n,true);check(debt.debt()==n&&debt.points()==0);var restored=WalletRules.adjustPoints(debt.points(),debt.debt(),n,false);check(restored.debt()==0&&restored.points()==0);var state=WalletRules.adjustPoints(n,0,-(n+1),true);check(state.points()==0&&state.debt()==1);}rejects(()->WalletRules.redeem(5,6,BigDecimal.ONE));rejects(()->WalletRules.balance(BigDecimal.ONE,new BigDecimal("-1.01")));rejects(()->WalletRules.points(Long.MAX_VALUE,1));rejects(()->WalletRules.adjustPoints(0,0,-1,false));check(WalletRules.balance(BigDecimal.TEN,BigDecimal.TEN.negate()).equals(new BigDecimal("0.00")));}
 public static void exports()throws Exception {var row=new LinkedHashMap<String,Object>();row.put("name","=SUM(1,2)");row.put("note","<hello & \"world\">\nline");row.put("amount",new BigDecimal("10.25"));var rows=List.<Map<String,Object>>of(row);String csv=new String(ReportExporter.csv(rows),StandardCharsets.UTF_8);check(csv.contains("'="));check(csv.contains("\"\"world\"\""));check(csv.contains("\r\n"));byte[] excel=ReportExporter.xlsx(rows);var factory=DocumentBuilderFactory.newInstance();factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);factory.setExpandEntityReferences(false);int files=0;try(var zip=new ZipInputStream(new ByteArrayInputStream(excel))){ZipEntry e;while((e=zip.getNextEntry())!=null){byte[] bytes=zip.readAllBytes();factory.newDocumentBuilder().parse(new ByteArrayInputStream(bytes));if(e.getName().endsWith("sheet1.xml")){String xml=new String(bytes,StandardCharsets.UTF_8);check(!xml.contains("<f>"));check(xml.contains("inlineStr"));check(xml.contains("&lt;hello &amp;"));}files++;}}check(files==5);check(ReportExporter.cell("  @command").startsWith("\"'"));}
 public static void main(String[] args)throws Exception{dining();money();signatures();wallet();exports();System.out.println("PASS: "+assertions+" executed Phase 9–15 production rule/export assertions");}
}
